/**
 * @description Monitor card for the scheduled jobs (admins only): whether the nightly clean-up and the four auto-retry
 * jobs are scheduled, their next run, the result of the last clean-up, the transactions waiting for auto-retry, and
 * scheduling the jobs again, which is needed after a sandbox refresh.
 * @group Integration Hub
 */
public with sharing class IntegrationHubCleanupStatus {

    /**
     * @description State of the nightly clean-up.
     */
    public class Status {
        /** @description True when the job exists. */
        @AuraEnabled public Boolean scheduled = false;
        /** @description Job state, e.g. WAITING. */
        @AuraEnabled public String state;
        /** @description Next scheduled start. */
        @AuraEnabled public Datetime nextRun;
        /** @description Last scheduled start. */
        @AuraEnabled public Datetime previousRun;
        /** @description User who scheduled the job; it runs as this user. */
        @AuraEnabled public String scheduledBy;
        /** @description When the last run finished and saved its result. */
        @AuraEnabled public Datetime lastFinished;
        /** @description Success transactions the last run deleted. */
        @AuraEnabled public Integer lastDeleted;
        /** @description Sent transactions the last run marked Failed for a missing callback. */
        @AuraEnabled public Integer lastTimedOut;
        /** @description How many of the four auto-retry jobs exist. */
        @AuraEnabled public Integer autoRetryJobs = 0;
        /** @description How many auto-retry jobs there should be (4: every 15 minutes). */
        @AuraEnabled public Integer autoRetryJobsExpected = 4;
        /** @description Next start of an auto-retry job. */
        @AuraEnabled public Datetime autoRetryNextRun;
        /** @description Failed outbound transactions waiting for auto-retry (counted up to 10,000). */
        @AuraEnabled public Integer waitingForRetry = 0;
        /** @description The earliest Next Retry At of those transactions. */
        @AuraEnabled public Datetime nextRetryAt;
    }

    /**
     * @description The clean-up job and the result of its last run.
     * @return the status
     */
    @AuraEnabled
    public static Status getStatus() {
        IntegrationHubMonitorController.requireAdmin();
        Status s = new Status();
        CronTrigger job = (CronTrigger) IntegrationHubData.queryFirst('SELECT State, NextFireTime, PreviousFireTime, '
            + 'CreatedBy.Name FROM CronTrigger WHERE CronJobDetail.Name = :name',
            new Map<String, Object>{ 'name' => IntegrationHubMaintenance.CLEANUP_JOB });
        if (job != null) {
            s.scheduled = true;
            s.state = job.State;
            s.nextRun = job.NextFireTime;
            s.previousRun = job.PreviousFireTime;
            s.scheduledBy = job.CreatedBy?.Name;
        }
        IH_Settings__c result = IH_Settings__c.getOrgDefaults();
        s.lastFinished = result.Last_Cleanup_At__c;
        s.lastDeleted = whole(result.Last_Cleanup_Deleted__c);
        s.lastTimedOut = whole(result.Last_Cleanup_Timed_Out__c);
        autoRetry(s);
        return s;
    }

    /**
     * @description Schedules the auto-retry jobs that are missing (every 15 minutes); they run as the current user.
     * @return the status afterwards
     */
    @AuraEnabled
    public static Status scheduleAutoRetry() {
        IntegrationHubMonitorController.requireAdmin();
        IntegrationHubAutoRetry.scheduleJobs();
        return getStatus();
    }

    private static void autoRetry(Status s) {
        s.autoRetryJobsExpected = IntegrationHubAutoRetry.jobNames().size();
        for (SObject row : IntegrationHubData.query('SELECT NextFireTime FROM CronTrigger WHERE CronJobDetail.Name IN :names',
                new Map<String, Object>{ 'names' => IntegrationHubAutoRetry.jobNames() })) {
            CronTrigger job = (CronTrigger) row;
            s.autoRetryJobs++;
            if (job.NextFireTime != null && (s.autoRetryNextRun == null || job.NextFireTime < s.autoRetryNextRun)) {
                s.autoRetryNextRun = job.NextFireTime;
            }
        }
        Map<String, Object> binds = new Map<String, Object>{ 'dir' => IntegrationHub.OUTBOUND, 'failed' => IntegrationHub.STATUS_FAILED };
        String waiting = 'FROM IH_Transaction__c WHERE ' + IntegrationHubAutoRetry.WAITING;
        s.waitingForRetry = IntegrationHubData.countQuery('SELECT COUNT() ' + waiting + ' LIMIT 10000', binds);
        IH_Transaction__c first = (IH_Transaction__c) IntegrationHubData.queryFirst('SELECT Next_Retry_At__c ' + waiting
            + ' ORDER BY Next_Retry_At__c ASC LIMIT 1', binds);
        s.nextRetryAt = first == null ? null : first.Next_Retry_At__c;
    }

    /**
     * @description Schedules the nightly clean-up at 02:00 (and the auto-retry jobs) when they are not scheduled; they
     * run as the current user.
     * @return the status afterwards
     */
    @AuraEnabled
    public static Status scheduleCleanup() {
        IntegrationHubMonitorController.requireAdmin();
        IntegrationHubMaintenance.scheduleAll();
        return getStatus();
    }

    @TestVisible
    private static Integer whole(Decimal value) {
        return value == null ? null : value.intValue();
    }
}
